<template>
  <DefaultLayout>
    <v-container :class="IS_CART_EMPTY ? 'v-col-6' : 'v-col-11'" fluid>
      <v-row>
        <v-col cols="12">
          <h1 class="text-center pb-3" v-if="!IS_CART_EMPTY">Shopping Cart</h1>
          <v-sheet elevation="0">
            <template v-if="!IS_CART_EMPTY">
              <v-sheet>
                <v-expand-transition>
                  <v-sheet v-if="model != null" height="600">
                    <div class="d-flex fill-height align-center justify-center pt-5">
                      <RedirectWidget v-if="model===0" :src="CART_LIST[0].image" :amount="this.vxCartTotalPrice"></RedirectWidget>
                      <EmbedWidget v-if="model===3" :amount="this.vxCartTotalPrice"></EmbedWidget>
                      <MobileWidget v-if="model===1" :amount="this.vxCartTotalPrice"></MobileWidget>
                      <CheckoutJsWidget v-if="model===2" :amount="this.vxCartTotalPrice"></CheckoutJsWidget>
                      <SimpleCardWidget v-if="model===4" :amount="this.vxCartTotalPrice"></SimpleCardWidget>
                    </div>
                  </v-sheet>
                </v-expand-transition>
                <v-slide-group
                    v-model="model"
                    class="pa-4"
                    show-arrows
                    mandatory
                >
                  <v-slide-group-item
                      v-for="n in checkouts"
                      :key="n"
                      v-slot="{ toggle, selectedClass }"
                  >
                    <v-card
                        :class="['ma-4', selectedClass]"
                        height="430"
                        width="300"
                        elevation="1"
                        @click="handleClick(toggle, n)"
                    >
                      <div class="d-flex flex-column pa-5">
                        <v-img height="220" :src="n.image"></v-img>
                        <h4 class="text-center mt-2 mb-5">{{ n.name }}</h4>
                        <span class="text-center">{{ n.description }}</span>
                      </div>
                    </v-card>
                  </v-slide-group-item>
                </v-slide-group>
              </v-sheet>
            </template>
            <template v-else>
              <section class="cart-empty-container">
                <div class="message-wrapper">
                  <h4 class="font-bold text-h6 py-3">{{ CONTENT.cartEmpty.title }}</h4>
                  <p class="font-thin">{{ CONTENT.cartEmpty.message }}</p>
                  <v-btn
                      :text="CONTENT.buttonText.shopNow"
                      variant="flat"
                      :color="colors.primary"
                      size="large"
                      class="my-5"
                      @click="goToHomepage">
                  </v-btn>
                </div>
                <img src="https://flitt.com/wp-content/uploads/2024/09/Group-67113.png" alt="guy holding a shopping cart" width="300"
                     height="400">
              </section>
            </template>
          </v-sheet>
        </v-col>
      </v-row>
    </v-container>
  </DefaultLayout>
</template>

<script>
import DefaultLayout from "@/layouts/DefaultLayout.vue";

import EmbedWidget from "@/components/widgets/Embed.vue";
import RedirectWidget from "@/components/widgets/Redirect.vue";
import MobileWidget from "@/components/widgets/Mobile.vue";
import CheckoutJsWidget from "@/components/widgets/CheckoutJs.vue";

import productMixins from "@/utils/product-mixins.js";
import STATIC_CONTENT from "@/static/content.json";
import colors from "@/utils/colors.js";

import checkout_redirect from "@/assets/images/checkout_redirect.png";
import embed_checkout from "@/assets/images/embed_checkout.png";
import mobile_checkout from "@/assets/images/mobile_checkout.png";
import widget_checkout from "@/assets/images/widget_checkout.png";
import simple_widget from "@/assets/images/simple_widget.png";

import {createNamespacedHelpers as nameSpace} from "vuex";
import SimpleCardWidget from "@/components/widgets/SimpleCardWidget.vue";


const {
  mapGetters: cartGetters,
  mapActions: cartActions,
} = nameSpace("cartModule");

export default {
  name: "Cart",
  mixins: [productMixins],
  components: {
    SimpleCardWidget,
    RedirectWidget,
    MobileWidget,
    CheckoutJsWidget,
    EmbedWidget,
    DefaultLayout,
  },
  data() {
    return {
      colors: colors,
      model: 3,
      checkouts: [
        {
          'name': 'Redirect checkout',
          'description': 'Use simple payment API with wide range of options to start accepting payments',
          'image': checkout_redirect,
          'widget': RedirectWidget
        },
        {
          'name': 'Mobile checkout',
          'description': 'Simple iOS, Android and React Native SDK’s and responsive mobile design',
          'image': mobile_checkout,
        },
        {
          'name': 'Checkout JS widget',
          'description': 'Simple JavaScript code that allows you start accept payments quickly and easy.',
          'image': widget_checkout,
        },
        {
          'name': 'Embedded checkout',
          'description': 'Create your unique payment form, built right into your site with Flitt JavaScript SDK.',
          'image': embed_checkout,
        },
          {
          'name': 'Simple card checkout',
          'description': 'Create a small card widget and accept payments.',
          'image': simple_widget,
        }
      ]
    };
  },
  computed: {
    ...cartGetters({
      vxCart: "cart",
      vxCartTotalPrice: "totalPrice",
    }),
    CART_LIST() {
      return JSON.parse(JSON.stringify(this.vxCart));
    },
    IS_CART_EMPTY() {
      return this.CART_LIST?.length === 0;
    },
    CONTENT() {
      return STATIC_CONTENT;
    },
  },
  methods: {
    ...cartActions([
      "updateCartVuex",
      "removeFromCartVuex",
      "clearCartVuex",
    ]),
    handleClick(toggle, n) {
      toggle();
    },
    async checkout() {
      const result = await this.mxCheckout(this.CART_LIST);
      if (!result) {
        return;
      }
      this.$router.push('/payment');
      this.clearCartVuex();
    },
    goToHomepage() {
      this.$router.push('/');
    },
  }
};
</script>

