<template>
  <div v-for="item in CART_LIST" :key="item.id" class="cart-item py-3 px-3">
    <div class="d-flex">
      <v-img
          :src="item.image"
          alt="cart item"
          width="100"
          style="max-width: 100px"
          contain
      ></v-img>
      <div class="ml-3 cart-name text-start">
        <span>{{ item.title }}</span>
        <div class="flex">
          <span class="price">{{ item.price }}</span> x <span>{{ item.quantity }}</span>
        </div>
      </div>
    </div>
    <v-icon :color="colors.primary" size="32" class="cursor-pointer cart-delete" @click="removeItemFromCart(item.id)">
      mdi-trash-can
    </v-icon>
  </div>
  <div class="font-bold big text-start pr-3 text-end pt-2">
      Total:&nbsp; <span class="price">{{ vxCartTotalPrice }}</span>
  </div>
</template>

<script>
import STATIC_CONTENT from "@/static/content.json";
import {createNamespacedHelpers as nameSpace} from "vuex";
import colors from "@/utils/colors";

const {
  mapGetters: cartGetters,
  mapActions: cartActions,
} = nameSpace("cartModule");

export default {
  props: {
    CONTENT: STATIC_CONTENT
  },
  computed: {
    colors() {
      return colors
    },
    ...cartGetters({
      vxCart: "cart",
      vxCartTotalPrice: "totalPrice",
    }),
    CART_LIST() {
      return JSON.parse(JSON.stringify(this.vxCart));
    },
  },
  methods: {
    ...cartActions([
      "removeFromCartVuex"
    ]),
    removeItemFromCart(itemId) {
      this.removeFromCartVuex(itemId);
    },
  }
};
</script>

<style scoped>
.cart-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid #ddd;
}

.cart-name {
  display: flex;
  flex-direction: column;
}

.price {
  font-weight: bold;
  color: #7D8FF8;
}
</style>
